from datetime import datetime, date
import re
from typing import Tuple, Optional

def validate_iso_date(date_str: str) -> Tuple[Optional[date], Optional[str]]:
    """Returns (parsed_date, error_message) where parsed_date is None and error_message is non-empty if invalid, or vice versa; rejects formats outside ISO 8601 (YYYY-MM-DD) and handles edge cases like leap years, invalid days, and invalid months deterministically."""
    pattern = r'^\d{4}-\d{2}-\d{2}$'
    if not re.match(pattern, date_str):
        return None, "Invalid format: must be YYYY-MM-DD"
    try:
        year, month, day = map(int, date_str.split('-'))
        if month < 1 or month > 12:
            return None, "Invalid month: must be between 1 and 12"
        if day < 1:
            return None, "Invalid day: must be at least 1"
        max_day = 31
        if month in [4, 6, 9, 11]:
            max_day = 30
        elif month == 2:
            if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
                max_day = 29
            else:
                max_day = 28
        if day > max_day:
            return None, f"Invalid day: must be <= {max_day}"
        return date(year, month, day), None
    except ValueError:
        return None, "Invalid date components"
