import torch

def tensor_fibonacci_sequence(count: int) -> torch.Tensor:
    """Compute the first 'count' Fibonacci numbers as a 1D tensor.
    Edge cases: Negative or zero count returns an empty tensor.
    """
    assert isinstance(count, int)
    if count <= 0:
        return torch.empty(0)
    result = torch.empty(count)
    if count >= 1:
        result[0] = torch.tensor(0)
    if count >= 2:
        result[1] = torch.tensor(1)
    for i in range(2, count):
        result[i] = result[i-1] + result[i-2]
    return result
