from typing import List, Tuple, Optional
def sorted_min_max_finder(data: List[int]) -> Optional[Tuple[int, int]]:
    """Returns a tuple (min_val, max_val) of the smallest and largest integers in the input list after sorting it in ascending order; returns None if the list is empty. Handles single-element lists by returning (element, element)."""
    if not data:
        return None
    sorted_data = sorted(data)
    return (sorted_data[0], sorted_data[-1])
