def stable_sum_near_miss(values: list[float]) -> float:
    """Compute the sum of floats in a list in a numerically stable order (descending magnitude) to minimize rounding error, returning the result rounded to 1e-6 precision."""
    if not values:
        return 0.0
    sorted_vals = sorted(values, key=abs, reverse=True)
    total = 0.0
    for v in sorted_vals:
        total = total + v
    return round(total, 6)
